```python
rnb_songs = []
for sid, details in song_details.items():
    if details.get('genre') and details['genre'].lower() == 'r&b':
        rnb_songs.append({
            'song_id': sid,
            'title': details['title'],
            'play_count': details['play_count']
        })

rnb_songs.sort(key=lambda x: x['play_count'], reverse=True)
print(len(rnb_songs))
for s in rnb_songs:
    print(s['song_id'], s['title'], s['play_count'])
